-- Arbeitsrecht Berufsbildung > Kündigungsschutz > Kündigungsschutzgesetz (KSchG) Anwendung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Gilt das Kündigungsschutzgesetz (KSchG) für einen Fachinformatiker während der Ausbildung?', 2, '[{"text": "Nein", "correct": true, "because": "§ 23 KSchG gilt nicht für Auszubildende, § 22 BBiG ist maßgeblich"}, {"text": "Ja", "correct": false, "because": "KSchG gilt nicht für Ausbildungsverhältnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker nach der Probezeit gemäß KSchG vor ordentlicher Kündigung geschützt sein?', 2, '[{"text": "Nein", "correct": true, "because": "§ 22 BBiG regelt den Kündigungsschutz, nicht das KSchG"}, {"text": "Ja", "correct": false, "because": "KSchG gilt nicht während der Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Betrieb bei der Kündigung eines Fachinformatikers die KSchG-Fristen einhalten?', 2, '[{"text": "Nein", "correct": true, "because": "§ 22 BBiG legt eigene Fristen fest, KSchG ist nicht anwendbar"}, {"text": "Ja", "correct": false, "because": "BBiG hat Vorrang"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker nach Abschluss der Ausbildung das KSchG in Anspruch nehmen?', 2, '[{"text": "Ja", "correct": true, "because": "Nach Übernahme in ein Arbeitsverhältnis gilt § 23 KSchG"}, {"text": "Nein", "correct": false, "because": "KSchG gilt bei festem Arbeitsverhältnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das KSchG für die außerordentliche Kündigung eines Fachinformatikers während der Ausbildung maßgeblich?', 2, '[{"text": "Nein", "correct": true, "because": "§ 22 Abs. 2 BBiG regelt dies, nicht das KSchG"}, {"text": "Ja", "correct": false, "because": "BBiG hat Vorrang"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt den Kündigungsschutz eines Fachinformatikers während der Ausbildung?', 2, '[{"text": "Berufsbildungsgesetz (BBiG)", "correct": true, "because": "§ 22 BBiG ist maßgeblich"}, {"text": "Kündigungsschutzgesetz (KSchG)", "correct": false, "because": "Gilt nicht für Auszubildende"}, {"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": false, "because": "Regelt Arbeitsschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wann gilt das Kündigungsschutzgesetz (KSchG) für einen Fachinformatiker?', 3, '[{"text": "Nach Übernahme in ein festes Arbeitsverhältnis", "correct": true, "because": "§ 23 KSchG gilt nach Ausbildungsende"}, {"text": "Während der Probezeit", "correct": false, "because": "BBiG gilt in der Ausbildung"}, {"text": "Nach der Zwischenprüfung", "correct": false, "because": "KSchG gilt nicht während der Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Warum gilt das KSchG nicht für einen Fachinformatiker während der Ausbildung?', 3, '[{"text": "Weil § 22 BBiG spezielle Regelungen für Auszubildende enthält", "correct": true, "because": "BBiG hat Vorrang"}, {"text": "Weil Auszubildende keine Arbeitnehmer sind", "correct": false, "because": "Nicht der Hauptgrund"}, {"text": "Weil die IHK dies bestimmt", "correct": false, "because": "IHK hat keine Regelungsbefugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frist gilt für die Kündigung eines Fachinformatikers nach der Probezeit?', 2, '[{"text": "4 Wochen zum Monatsende gemäß § 22 BBiG", "correct": true, "because": "BBiG regelt dies"}, {"text": "2 Monate gemäß KSchG", "correct": false, "because": "KSchG gilt nicht"}, {"text": "Keine Frist", "correct": false, "because": "Frist ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Betrieb einen Fachinformatiker nach der Ausbildung übernimmt und dann kündigt?', 3, '[{"text": "Das KSchG gilt, wenn die Voraussetzungen erfüllt sind", "correct": true, "because": "§ 23 KSchG greift bei Arbeitsverhältnis"}, {"text": "Die Kündigung ist automatisch unwirksam", "correct": false, "because": "KSchG prüft nur bei Klage"}, {"text": "Das BBiG bleibt maßgeblich", "correct": false, "because": "BBiG gilt nur während der Ausbildung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Regelungen gelten für die Kündigung eines Fachinformatikers während der Ausbildung?', 4, '[{"text": "§ 22 BBiG regelt die Kündigung", "correct": true, "because": "BBiG hat Vorrang"}, {"text": "KSchG gilt nicht für Auszubildende", "correct": true, "because": "§ 23 KSchG schließt dies aus"}, {"text": "KSchG schützt nach der Probezeit", "correct": false, "because": "BBiG ist maßgeblich"}, {"text": "Schriftform ist erforderlich", "correct": true, "because": "§ 22 Abs. 2 BBiG fordert dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzungen müssen erfüllt sein, damit das KSchG auf einen Fachinformatiker anwendbar ist?', 3, '[{"text": "Übernahme in ein Arbeitsverhältnis", "correct": true, "because": "§ 23 KSchG gilt nach Ausbildung"}, {"text": "Mindestens 6 Monate Betriebszugehörigkeit", "correct": true, "because": "§ 23 KSchG setzt dies voraus"}, {"text": "Probezeit abgeschlossen", "correct": false, "because": "KSchG gilt nicht während der Ausbildung"}, {"text": "Betrieb mit mehr als 10 Mitarbeitern", "correct": true, "because": "§ 23 KSchG Anwendungsvoraussetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gilt für die Kündigung eines Fachinformatikers nach der Ausbildung, wenn er übernommen wird?', 4, '[{"text": "KSchG kann anwendbar sein", "correct": true, "because": "§ 23 KSchG greift bei Arbeitsverhältnis"}, {"text": "Soziale Rechtfertigung erforderlich", "correct": true, "because": "§ 1 KSchG verlangt dies"}, {"text": "BBiG bleibt maßgeblich", "correct": false, "because": "BBiG gilt nur während der Ausbildung"}, {"text": "Kündigungsfristen gemäß KSchG", "correct": true, "because": "§ 622 BGB über KSchG gilt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede bestehen zwischen KSchG und BBiG bei der Kündigung eines Fachinformatikers?', 3, '[{"text": "KSchG gilt nicht während der Ausbildung, BBiG schon", "correct": true, "because": "§ 23 KSchG vs. § 22 BBiG"}, {"text": "BBiG verlangt wichtigen Grund nach Probezeit, KSchG soziale Rechtfertigung", "correct": true, "because": "Unterschiedliche Anforderungen"}, {"text": "KSchG hat kürzere Fristen als BBiG", "correct": false, "because": "BBiG hat spezifische Fristen"}, {"text": "BBiG gilt nur nach Übernahme", "correct": false, "because": "BBiG gilt während der Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gilt nicht für die Kündigung eines Fachinformatikers während der Ausbildung?', 3, '[{"text": "Schriftform gemäß § 22 BBiG", "correct": false, "because": "Pflicht nach BBiG"}, {"text": "Wichtiger Grund nach Probezeit gemäß § 22 BBiG", "correct": false, "because": "Pflicht nach BBiG"}, {"text": "Soziale Rechtfertigung gemäß KSchG", "correct": true, "because": "KSchG gilt nicht"}, {"text": "Frist von 4 Wochen gemäß § 22 BBiG", "correct": false, "because": "Pflicht nach BBiG"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das KSchG gilt nicht für einen Fachinformatiker während der Ausbildung. b) Nach der Probezeit schützt das KSchG vor Kündigung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "KSchG gilt nicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) § 22 BBiG regelt die Kündigung eines Fachinformatikers während der Ausbildung. b) Das KSchG gilt nach Übernahme in ein Arbeitsverhältnis.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 22 BBiG und § 23 KSchG bestätigen dies"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das KSchG verlangt soziale Rechtfertigung für Kündigungen. b) Während der Ausbildung gilt diese Regel für einen Fachinformatiker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "KSchG fordert Rechtfertigung, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Fachinformatiker kann nach der Ausbildung das KSchG nutzen. b) Während der Probezeit schützt das KSchG vor Kündigung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "KSchG nach Übernahme, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das BBiG hat Vorrang vor dem KSchG während der Ausbildung. b) Nach der Ausbildung gilt nur das BBiG für einen Fachinformatiker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "BBiG gilt während Ausbildung, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

